target_em=610
idset=set(ids)
for p in prots:
    states=p.get('states',[])
    pdb_ids=set(p.get('pdb',[]) or [])
    for st in states:
        ex=st.get('ex_max')
        em=st.get('em_max')
        if ex==target_ex or em==target_em:
            print('FP match:', p.get('name'), 'slug', p.get('slug'), 'pdb', pdb_ids, 'ex', ex, 'em', em, 'seqlen', len(p.get('seq','')), 'uuid', p.get('uuid'), flush=True)
