import urllib.request, urllib.parse, json, re, sys, time

# Read antibody sequences
seqs={}
cur=None
for line in open('/app/antibody.fasta'):
    line=line.strip()
    if line.startswith('>'):
        cur=line[1:].split()[0]
        seqs[cur]=''
    elif cur:
        seqs[cur]+=line
print('Antibody seqs:', {k:len(v) for k,v in seqs.items()}, flush=True)
heavy=seqs.get('heavy','')
light=seqs.get('light','')
print('Heavy first 80:', heavy[:80], flush=True)
print('Light first 80:', light[:80], flush=True)

# Try NCBI BLAST URLAPI for heavy chain CDR3 region or full sequence
# Use the full heavy chain variable region
for name,seq in [('heavy',heavy),('light',light)]:
    print('\n=== BLAST', name, '===', flush=True)
    params={
        'CMD':'Put',
        'PROGRAM':'blastp',
        'DATABASE':'nr',
        'QUERY':seq,
        'FORMAT_TYPE':'JSON2',
        'HITLIST_SIZE':'10',
        'EXPECT':'10',
    }
    try:
        data=urllib.parse.urlencode(params).encode()
        req=urllib.request.Request('https://blast.ncbi.nlm.nih.gov/Blast.cgi', data=data, headers={'User-Agent':'Mozilla/5.0'})
        resp=urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
        rid=re.search(r'RID = (\S+)', resp)
        if rid:
            rid=rid.group(1)
            print('RID', rid, flush=True)
            for i in range(20):
                time.sleep(8)
                gparams={'CMD':'Get','FORMAT_OBJECT':'SearchInfo','RID':rid}
                greq=urllib.request.Request('https://blast.ncbi.nlm.nih.gov/Blast.cgi?'+urllib.parse.urlencode(gparams), headers={'User-Agent':'Mozilla/5.0'})
                gresp=urllib.request.urlopen(greq, timeout=30).read().decode('utf-8','replace')
                status=re.search(r'Status=(\S+)', gresp)
                if status:
                    print('status', status.group(1), flush=True)
                    if status.group(1) in ('READY','FAILED','UNKNOWN'):
                        if status.group(1)=='READY':
                            rparams={'CMD':'Get','FORMAT_TYPE':'JSON2','ALIGNMENT_VIEW':'Pairwise','RID':rid,'RESULTS_FILE':'true'}
                            rreq=urllib.request.Request('https://blast.ncbi.nlm.nih.gov/Blast.cgi?'+urllib.parse.urlencode(rparams), headers={'User-Agent':'Mozilla/5.0'})
                            rresp=urllib.request.urlopen(rreq, timeout=60).read().decode('utf-8','replace')
                            print('Results snippet:', rresp[:3000], flush=True)
                        break
                else:
                    print('no status, snippet:', gresp[:500], flush=True)
                    break
        else:
            print('No RID found, resp snippet:', resp[:1000], flush=True)
    except Exception as e:
        print('BLAST ERR', name, repr(e), flush=True)
